'use strict';
// Repair the element-first MCQ handlers in course lesson pages.
//
// Seven lessons shipped options whose inline handlers named a function the
// page never defined, or called an id-first runtime with `this`:
//
//   selectOption(this,1,'correct')  -> no selectOption()
//   selOpt(this,false)              -> no selOpt()
//   selectOpt(this,false)           -> selectOpt(qId,idx) existed, so `this`
//                                      became qId and the click did nothing
//   checkAnswer(this,'b')           -> no checkAnswer()
//
// The markup is generated by several one-off writers, so this script is the
// deterministic, rerunnable repair: it renames the static calls that collide
// with an id-first runtime, then adds a tiny alias block backed by
// js/quiz-static.js. It is idempotent and never touches the dynamic quiz.
//
//   node scripts/fix-static-quiz-handlers.js [--check]
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const CHECK = process.argv.indexOf('--check') !== -1;
const MARKER = '<!-- static-quiz-handlers -->';
const MARKER_END = '<!-- /static-quiz-handlers -->';

const TARGETS = [
  'cds/course/gk/lesson-current-affairs.html',
  'upsc/course/gs/lesson-current-affairs.html',
  'neet/course/biology/lesson-ecology.html',
  'upsc/course/gs/lesson-general-science.html',
  'upsc/course/gs/lesson-indian-economy.html',
  'nda/course/gat/lesson-general-science.html',
  'ssc-gd/course/gk/lesson-general-science.html'
];

function hasDefinition(html, name) {
  return new RegExp('function\\s+' + name + '\\s*\\(').test(html) ||
    new RegExp('\\b' + name + '\\s*=\\s*(?:async\\s*)?function\\b').test(html);
}

function aliasFor(name) {
  if (name === 'selectOption') {
    return 'function selectOption(el, idx, verdict) { return QuizStatic.answer(el, verdict === \'correct\'); }';
  }
  if (name === 'checkAnswer') {
    return 'function checkAnswer(el, letter) { return QuizStatic.checkLetter(el, letter); }';
  }
  return 'function ' + name + '(el, isCorrect) { return QuizStatic.answer(el, isCorrect); }';
}

let changed = 0;
TARGETS.forEach(function (rel) {
  const file = path.join(ROOT, rel);
  let html = fs.readFileSync(file, 'utf8');
  const before = html;

  // Remove a previous managed block before deciding what is missing, otherwise
  // the aliases this script added would count as pre-existing definitions and
  // the next run would quietly delete them.
  const start = html.indexOf(MARKER);
  if (start !== -1) {
    const end = html.indexOf(MARKER_END, start);
    if (end === -1) throw new Error(rel + ': managed block has no end marker');
    // Consume the newline that follows the end marker. The block is inserted
    // directly before </body> after an existing newline; leaving that newline
    // behind would add one more on every run and make the repair non-idempotent.
    const after = html.slice(end + MARKER_END.length).replace(/^\r?\n/, '');
    html = html.slice(0, start) + after;
  }

  // A page that also runs the id-first quiz keeps selectOpt(qId,idx). Rename
  // only the static `this` calls so the two contracts stop colliding.
  if (hasDefinition(html, 'selectOpt')) {
    html = html.replace(/onclick="selectOpt\(this,/g, 'onclick="selectStaticOpt(this,');
  }

  const names = ['selectOption', 'selectOpt', 'selOpt', 'selectStaticOpt', 'checkAnswer'].filter(function (name) {
    return new RegExp('onclick="' + name + '\\s*\\(\\s*this').test(html);
  });
  const missing = names.filter(function (name) { return !hasDefinition(html, name); });

  if (missing.length) {
    const helper = path.relative(path.dirname(file), path.join(ROOT, 'js/quiz-static.js')).replace(/\\/g, '/');
    const block = MARKER + '\n' +
      '<script src="' + helper + '"></script>\n' +
      '<script>\n' + missing.map(aliasFor).join('\n') + '\n</script>\n' +
      MARKER_END + '\n';
    const body = html.lastIndexOf('</body>');
    if (body === -1) throw new Error(rel + ': no </body>');
    html = html.slice(0, body) + block + html.slice(body);
  }

  if (html !== before) {
    changed++;
    if (CHECK) console.log('WOULD FIX  ' + rel + '  (' + (missing.join(', ') || 'rename only') + ')');
    else {
      fs.writeFileSync(file, html);
      console.log('fixed      ' + rel + '  (' + (missing.join(', ') || 'rename only') + ')');
    }
  } else {
    console.log('unchanged  ' + rel);
  }
});

console.log('\n' + changed + ' file(s) ' + (CHECK ? 'need repair' : 'repaired'));
process.exit(CHECK && changed ? 1 : 0);
